119	\begin{proposition}[Purely inseparable maps]\label{ha-ch4-p25}\dcref{IV.2.5}
120	\source{hartshorne-algebraic-geometry:IV.2.5}
121	If \(K(X)/K(Y)\) is purely inseparable, \(X,Y\) are abstractly isomorphic,
122	\(f\) is a composite of relative Frobenius maps, and \(g(X)=g(Y)\).
123	\end{proposition}
124	\begin{proof}
125	For degree \(p^r\), \(K(X)=K(Y)^{1/p^r}\).  The composite relative Frobenius
126	has this extension, and curves are determined by their function fields.
127	\end{proof}
