129	\section{Embeddings in Projective Space}
130	\label{ha-ch4-s3}\source{hartshorne-algebraic-geometry:IV.3}
131	\begin{proposition}[Linear systems]\label{ha-ch4-p31}\dcref{IV.3.1}
132	\source{hartshorne-algebraic-geometry:IV.3.1}
133	\(|D|\) is base-point-free iff \(\dim|D-P|=\dim|D|-1\) for all \(P\); \(D\)
134	is very ample iff \(\dim|D-P-Q|=\dim|D|-2\) for all \(P,Q\), including
135	\(P=Q\).
136	\end{proposition}
137	\begin{proof}
138	The exact sequence at \(P\) identifies the surjectivity of
139	\(|D-P|\to|D|\) with a base point.  The closed-immersion criterion translates
140	separation of points and tangent vectors into the two stated dimension drops.
141	\end{proof}
142	
143	\begin{corollary}[Numerical bounds]\label{ha-ch4-c32}\dcref{IV.3.2}
144	\source{hartshorne-algebraic-geometry:IV.3.2}
145	\(\deg D\ge2g\) implies no base points, and \(\deg D\ge2g+1\) implies very
146	ample.
147	\uses{ha-ch4-p31}
148	\end{corollary}
149	\begin{proof}
150	Riemann--Roch makes the relevant \(D-P\), respectively \(D-P-Q\), nonspecial,
151	and Proposition 3.1 applies.
152	\end{proof}
153	
154	\begin{corollary}[Ample divisors]\label{ha-ch4-c33}\dcref{IV.3.3}
155	\source{hartshorne-algebraic-geometry:IV.3.3}
156	\(D\) is ample iff \(\deg D>0\).
157	\uses{ha-ch4-c32}
158	\end{corollary}
159	\begin{proof}
160	An ample divisor has a positive-degree very ample multiple.  A positive-degree
161	divisor has a very ample multiple by Corollary 3.2.
162	\end{proof}
163	
164	\begin{proposition}[Projection criterion]\label{ha-ch4-p34}\dcref{IV.3.4}
165	\source{hartshorne-algebraic-geometry:IV.3.4}
166	Projection from \(O\notin X\subset\mathbf P^n\) is a closed immersion iff
167	\(O\) lies on no secant and no tangent line of \(X\).
168	\end{proposition}
169	\begin{proof}
170	The projection system is cut out by hyperplanes through \(O\).  Such
171	hyperplanes separate points exactly off secants and tangent vectors exactly
172	off tangent lines.
173	\end{proof}
174	
175	\begin{proposition}[Projection dimension]\label{ha-ch4-p35}\dcref{IV.3.5}
176	\source{hartshorne-algebraic-geometry:IV.3.5}
177	If \(X\subset\mathbf P^n\) is a curve and \(n\ge4\), some projection embeds it
178	in \(\mathbf P^{n-1}\).
179	\uses{ha-ch4-p34}
180	\end{proposition}

